#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Wizard-local helper. Railway values are pushed one key at a time through
# --stdin so a secret never appears in the process argument list.

RAILWAY_KEYS=()
RAILWAY_PAIRS=()

railway_set() {
  RAILWAY_KEYS+=("$1")
  RAILWAY_PAIRS+=("$1=$2")
}

railway_linked() {
  command -v railway >/dev/null 2>&1 || return 1
  railway status >/dev/null 2>&1
}

push_railway_vars() {
  if (( ${#RAILWAY_PAIRS[@]} == 0 )); then
    return 0
  fi
  if ! command -v railway >/dev/null 2>&1; then
    SKIPPED+=("Railway variables not pushed (CLI missing). Set by hand: ${RAILWAY_KEYS[*]}")
    warn "Railway CLI missing; values are only recorded in $ENV_FILE."
    return 0
  fi
  if ! railway status >/dev/null 2>&1; then
    SKIPPED+=("Railway variables not pushed (service not linked). Set by hand: ${RAILWAY_KEYS[*]}")
    warn "Railway service is not linked; run 'railway link' and re-run this wizard."
    return 0
  fi

  local pair key value failed=0
  for pair in "${RAILWAY_PAIRS[@]}"; do
    key="${pair%%=*}"
    value="${pair#*=}"
    if printf '%s' "$value" | railway variable set "$key" --stdin --skip-deploys >/dev/null 2>&1; then
      printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$key"
    elif railway variables --set "$key=$value" --skip-deploys </dev/null >/dev/null 2>&1; then
      # Older CLI without the `variable set` subcommand.
      printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$key"
    else
      failed=$((failed + 1))
      warn "could not set $key"
    fi
  done

  if (( failed == 0 )); then
    say "Pushed ${#RAILWAY_PAIRS[@]} variable(s) to Railway."
    RAILWAY_PAIRS=()
    RAILWAY_KEYS=()
  else
    SKIPPED+=("Railway variables: $failed key(s) not pushed; set them in the dashboard")
  fi
}

random_secret() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex 32
  elif command -v node >/dev/null 2>&1; then
    node -e 'process.stdout.write(require("crypto").randomBytes(32).toString("hex"))'
  fi
}

TOTAL_STAGES=14

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd "$SCRIPT_DIR/.." && pwd)
cd "$REPO_ROOT"

banner "Cloudflare + R2 + Railway setup"

# ──────────────────────────────────────────────────────────────────────────

stage "Preflight"
say "This walks the existing monorepo onto the target architecture:"
say "Cloudflare (DNS/CDN) → Railway Singapore (Next.js) → Neon + Upstash,"
say "with media in a private Cloudflare R2 bucket."
say ""
note "Nothing is provisioned automatically. You click in the dashboards and this"
note "records what you copy back, so a re-run resumes where you stopped."
warn "Values are saved to $ENV_FILE. It is gitignored, but it will contain"
warn "production credentials: never commit, copy, or share it."
note "The app does not read this repo-root file at runtime; Railway service"
note "variables are what production uses."
say ""
say "Checking the environment..."

if [[ -f package.json && -f Dockerfile ]]; then
  printf '  %s✓%s repository root: %s\n' "$GREEN" "$RESET" "$PWD"
else
  warn "package.json or Dockerfile is missing in $PWD"
  exit 1
fi

if command -v node >/dev/null 2>&1; then
  node_major=$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)
  if [[ "$node_major" -ge 20 ]]; then
    printf '  %s✓%s node %s\n' "$GREEN" "$RESET" "$(node -v)"
  else
    warn "node $(node -v) is older than the Node 20 used by the Dockerfile"
  fi
else
  warn "node not found; local migrations and secret generation need it"
fi

if command -v npm >/dev/null 2>&1; then
  printf '  %s✓%s npm %s\n' "$GREEN" "$RESET" "$(npm -v)"
else
  warn "npm not found; the migrations stage will not run"
fi

if [[ -d node_modules ]]; then
  printf '  %s✓%s node_modules present\n' "$GREEN" "$RESET"
else
  warn "node_modules missing; run 'npm install' before the migrations stage"
fi

if command -v curl >/dev/null 2>&1; then
  printf '  %s✓%s curl available\n' "$GREEN" "$RESET"
else
  warn "curl not found; the smoke test stage will be skipped"
fi

if command -v railway >/dev/null 2>&1; then
  printf '  %s✓%s railway CLI available\n' "$GREEN" "$RESET"
else
  warn "railway CLI not found; variables will only be recorded in $ENV_FILE"
  note "install it with: npm i -g @railway/cli"
fi

pause

# ──────────────────────────────────────────────────────────────────────────

stage "Cloudflare R2 · create a private bucket"
say "Media lives in R2 and is read through short-lived signed URLs, so the"
say "bucket stays private. There is no public bucket URL to leak."
open_url "https://dash.cloudflare.com/?to=/:account/r2"
step "R2 → Create bucket."
step "Name it, for example wedding-assets-prod."
step "Location: Asia Pacific (APAC)."
step "Leave public access DISABLED; do not enable an r2.dev subdomain."
pause "Press Enter once the bucket exists"
ask STORAGE_BUCKET "Bucket name:"
if [[ -z "$STORAGE_BUCKET" ]]; then
  warn "A bucket name is required."
  exit 1
fi
write_env STORAGE_BUCKET "$STORAGE_BUCKET"
railway_set STORAGE_BUCKET "$STORAGE_BUCKET"



stage "Cloudflare R2 · S3 API token"
say "R2 exposes an S3-compatible API. Railway signs upload and read URLs with"
say "these keys; they never reach the browser."
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "Manage R2 API Tokens → Create API token."
step "Permissions: Object Read & Write."
step "Scope it to the bucket from the previous stage only."
step "Copy the Access Key ID and the Secret Access Key. The secret is shown once."
pause "Press Enter when the token is created"
ask CLOUDFLARE_ACCOUNT_ID "Cloudflare Account ID:"
if [[ ! "$CLOUDFLARE_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]]; then
  warn "That is not 32 hex characters, which is what a Cloudflare account ID is."
  if ! confirm "Use it anyway?"; then
    exit 1
  fi
fi
ask STORAGE_ACCESS_KEY_ID "Access Key ID:"
ask_secret STORAGE_SECRET_ACCESS_KEY "Secret Access Key:"

STORAGE_ENDPOINT="https://${CLOUDFLARE_ACCOUNT_ID}.r2.cloudflarestorage.com"
say "Endpoint derived from the account ID:"
note "$STORAGE_ENDPOINT"

write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
write_env STORAGE_ENDPOINT "$STORAGE_ENDPOINT"
write_env STORAGE_ACCESS_KEY_ID "$STORAGE_ACCESS_KEY_ID"
write_env STORAGE_SECRET_ACCESS_KEY "$STORAGE_SECRET_ACCESS_KEY"
railway_set STORAGE_ENDPOINT "$STORAGE_ENDPOINT"
railway_set STORAGE_ACCESS_KEY_ID "$STORAGE_ACCESS_KEY_ID"
railway_set STORAGE_SECRET_ACCESS_KEY "$STORAGE_SECRET_ACCESS_KEY"

# ──────────────────────────────────────────────────────────────────────────

stage "Cloudflare R2 · CORS for direct uploads"
say "The browser uploads straight to R2 after Railway authorizes the upload."
say "R2 must therefore accept a presigned PUT from the app origin."
note "The presigned URL signs content-type;host, so the browser must send the"
note "exact Content-Type Railway signed. That is the only header to allow."
say ""
ask APP_URL "Public app origin (e.g. https://example.com):"
case "$APP_URL" in
  https://*) ;;
  http://localhost*) ;;
  *) warn "APP_URL should be an https origin." ;;
esac
if [[ -z "$APP_URL" ]]; then
  warn "APP_URL is required: it is the origin the browser uploads from."
  exit 1
fi
ask APP_URL_ALT "Second origin (e.g. https://www.example.com), blank to skip:"

origins_json="\"$APP_URL\""
if [[ -n "$APP_URL_ALT" ]]; then
  origins_json+=", \"$APP_URL_ALT\""
fi
origins_json+=", \"http://localhost:3000\""

say ""
say "Cloudflare dashboard → R2 → $STORAGE_BUCKET → Settings → CORS Policy → Edit."
say "Paste exactly this:"
say ""
printf '[\n'
printf '  {\n'
printf '    "AllowedOrigins": [%s],\n' "$origins_json"
printf '    "AllowedMethods": ["GET", "HEAD", "PUT"],\n'
printf '    "AllowedHeaders": ["Content-Type"],\n'
printf '    "ExposeHeaders": ["ETag"],\n'
printf '    "MaxAgeSeconds": 3600\n'
printf '  }\n'
printf ']\n'
say ""
note "GET/HEAD cover signed read URLs; PUT covers the direct upload. R2 answers"
note "the preflight automatically, so OPTIONS is not listed."
note "Another deploy origin later? Add it here, or uploads fail with a CORS error."

write_env APP_URL "$APP_URL"
if [[ -n "$APP_URL_ALT" ]]; then
  write_env APP_URL_ALT "$APP_URL_ALT"
fi
if ! confirm "Has R2 saved the CORS policy?"; then
  SKIPPED+=("Save the R2 CORS policy shown above for $STORAGE_BUCKET")
fi

# ──────────────────────────────────────────────────────────────────────────

stage "Railway · project, service, region"
say "Railway runs the Next.js app, its API, and payment webhooks."
say "The repository Dockerfile builds from the monorepo root."
open_url "https://railway.com/new"
step "New Project → Deploy from a GitHub repo → select this repository."
step "Open the service → Settings → Source → confirm the Dockerfile builder."
step "Settings → Region → Singapore."
note "railway.json pins the Dockerfile and the /api/health healthcheck."
say ""
if command -v railway >/dev/null 2>&1; then
  if railway_linked; then
    say "Railway CLI is linked to a project."
  else
    warn "Railway CLI is installed but not linked."
    note "In another terminal: railway login && railway link"
    pause "Press Enter after linking (press Enter alone to skip CLI pushes)"
  fi
else
  note "No Railway CLI: variables are only recorded in $ENV_FILE."
fi

# ──────────────────────────────────────────────────────────────────────────

stage "Neon · Postgres connection strings"
say "Neon is the source of truth. Keep it in the same region as Railway."
open_url "https://console.neon.tech/app/projects"
step "Create a project. Region: AWS ap-southeast-1 (Singapore)."
step "Open Dashboard → Connect."
step "Copy the POOLED connection string (its host contains '-pooler')."
step "Copy the DIRECT unpooled connection string as well."
note "Prisma uses DATABASE_URL at runtime and DIRECT_URL for migrations."
say ""
ask_secret DATABASE_URL "DATABASE_URL (pooled):"
ask_secret DIRECT_URL "DIRECT_URL (direct):"
if [[ -z "$DATABASE_URL" || -z "$DIRECT_URL" ]]; then
  warn "Both connection strings are required."
  exit 1
fi
if [[ "$DATABASE_URL" != *"-pooler"* ]]; then
  warn "DATABASE_URL has no '-pooler' host; confirm it is the pooled string."
fi
if [[ "$DIRECT_URL" == *"-pooler"* ]]; then
  warn "DIRECT_URL looks pooled; migrations need the direct endpoint."
fi
write_env DATABASE_URL "$DATABASE_URL"
write_env DIRECT_URL "$DIRECT_URL"
railway_set DATABASE_URL "$DATABASE_URL"
railway_set DIRECT_URL "$DIRECT_URL"

# ──────────────────────────────────────────────────────────────────────────

stage "Upstash · Redis REST credentials"
say "Upstash caches public invitations and backs analytics rate limiting."
say "If it is unreachable, public pages fall back to Postgres instead of failing."
open_url "https://console.upstash.com/redis"
step "Create Database → Regional → ap-southeast-1 (Singapore)."
step "Open the database → REST API."
step "Copy the REST URL and the REST token."
say ""
ask UPSTASH_REDIS_REST_URL "UPSTASH_REDIS_REST_URL:"
ask_secret UPSTASH_REDIS_REST_TOKEN "UPSTASH_REDIS_REST_TOKEN:"
if [[ -z "$UPSTASH_REDIS_REST_URL" || -z "$UPSTASH_REDIS_REST_TOKEN" ]]; then
  warn "Leave both blank and the app still runs, just without cache."
  if ! confirm "Continue without Redis?"; then
    exit 1
  fi
else
  write_env UPSTASH_REDIS_REST_URL "$UPSTASH_REDIS_REST_URL"
  write_env UPSTASH_REDIS_REST_TOKEN "$UPSTASH_REDIS_REST_TOKEN"
  railway_set UPSTASH_REDIS_REST_URL "$UPSTASH_REDIS_REST_URL"
  railway_set UPSTASH_REDIS_REST_TOKEN "$UPSTASH_REDIS_REST_TOKEN"
fi

# ──────────────────────────────────────────────────────────────────────────

stage "Railway · application secrets"
say "APP_URL is the canonical public origin: verification links, share URLs,"
say "and payment callbacks are built from it."
ask APP_URL "APP_URL:"
say ""
say "AUTH_SECRET seals MFA TOTP secrets at rest with AES-256-GCM."
say "Keep it stable: changing it invalidates every enrolled second factor."
ask_secret AUTH_SECRET "AUTH_SECRET (blank generates one):"
if [[ -z "$AUTH_SECRET" ]]; then
  AUTH_SECRET="$(random_secret)"
  if [[ -z "$AUTH_SECRET" ]]; then
    warn "openssl and node are both missing, so no secret could be generated."
    exit 1
  fi
  say "Generated a 64-character AUTH_SECRET."
fi
say ""
say "ANALYTICS_HASH_SECRET hashes visitor identifiers and must be at least 32"
say "characters. Without it the analytics API answers 503."
ask_secret ANALYTICS_HASH_SECRET "ANALYTICS_HASH_SECRET (blank generates one):"
if [[ -z "$ANALYTICS_HASH_SECRET" ]]; then
  ANALYTICS_HASH_SECRET="$(random_secret)"
  if [[ -z "$ANALYTICS_HASH_SECRET" ]]; then
    warn "openssl and node are both missing, so no secret could be generated."
    exit 1
  fi
  say "Generated a 64-character ANALYTICS_HASH_SECRET."
fi
if [[ ${#ANALYTICS_HASH_SECRET} -lt 32 ]]; then
  warn "ANALYTICS_HASH_SECRET is shorter than 32 characters; analytics will 503."
  if ! confirm "Continue anyway?"; then
    exit 1
  fi
fi

write_env APP_URL "$APP_URL"
write_env AUTH_SECRET "$AUTH_SECRET"
write_env ANALYTICS_HASH_SECRET "$ANALYTICS_HASH_SECRET"
write_env NEXT_PUBLIC_SITE_URL "$APP_URL"
write_env ADMIN_PRODUCTION_MUTATIONS_APPROVED "false"
write_env ADMIN_PAYMENT_PRODUCTION_APPROVED "false"

railway_set APP_URL "$APP_URL"
railway_set AUTH_SECRET "$AUTH_SECRET"
railway_set ANALYTICS_HASH_SECRET "$ANALYTICS_HASH_SECRET"
railway_set ADMIN_PRODUCTION_MUTATIONS_APPROVED "false"
railway_set ADMIN_PAYMENT_PRODUCTION_APPROVED "false"
railway_set NEXT_PUBLIC_SITE_URL "$APP_URL"
note "NEXT_PUBLIC_SITE_URL is inlined at build time: changing it needs a rebuild."

# ──────────────────────────────────────────────────────────────────────────

stage "Railway · notifications and payments"
say "Production refuses the console notification transport, so email and"
say "WhatsApp need an HTTP relay. Blank leaves them disabled (fail-closed)."
ask NOTIFICATION_RELAY_URL "NOTIFICATION_RELAY_URL (blank to skip):"
if [[ -n "$NOTIFICATION_RELAY_URL" ]]; then
  ask_secret NOTIFICATION_RELAY_API_KEY "NOTIFICATION_RELAY_API_KEY:"
  if [[ -z "$NOTIFICATION_RELAY_API_KEY" ]]; then
    warn "A relay URL without an API key fails closed."
    SKIPPED+=("Set NOTIFICATION_RELAY_API_KEY for the configured relay")
  else
    write_env EMAIL_PROVIDER "relay"
    write_env NOTIFICATION_RELAY_URL "$NOTIFICATION_RELAY_URL"
    write_env NOTIFICATION_RELAY_API_KEY "$NOTIFICATION_RELAY_API_KEY"
    railway_set EMAIL_PROVIDER "relay"
    railway_set NOTIFICATION_RELAY_URL "$NOTIFICATION_RELAY_URL"
    railway_set NOTIFICATION_RELAY_API_KEY "$NOTIFICATION_RELAY_API_KEY"
  fi
else
  warn "Notifications stay disabled in production (PROVIDER_UNAVAILABLE)."
  SKIPPED+=("Configure EMAIL_PROVIDER=relay plus relay URL/key to enable notifications")
fi

say ""
say "Payments: Midtrans QRIS. Anything other than 'production' uses sandbox."
ask MIDTRANS_ENVIRONMENT "MIDTRANS_ENVIRONMENT (sandbox or production) [sandbox]:"
if [[ -z "$MIDTRANS_ENVIRONMENT" ]]; then
  MIDTRANS_ENVIRONMENT="sandbox"
fi
ask_secret MIDTRANS_SERVER_KEY "MIDTRANS_SERVER_KEY (blank disables payments):"
if [[ -n "$MIDTRANS_SERVER_KEY" ]]; then
  write_env MIDTRANS_ENVIRONMENT "$MIDTRANS_ENVIRONMENT"
  write_env MIDTRANS_SERVER_KEY "$MIDTRANS_SERVER_KEY"
  railway_set MIDTRANS_ENVIRONMENT "$MIDTRANS_ENVIRONMENT"
  railway_set MIDTRANS_SERVER_KEY "$MIDTRANS_SERVER_KEY"
  note "Webhook signature verification uses this same server key."
else
  warn "No server key: the QRIS port stays disabled and webhooks answer 503."
  SKIPPED+=("Set MIDTRANS_SERVER_KEY to enable payments")
fi

# ──────────────────────────────────────────────────────────────────────────

stage "Railway · apply service variables"
if (( ${#RAILWAY_PAIRS[@]} > 0 )); then
  say "Pushing ${#RAILWAY_PAIRS[@]} variable(s) to the linked Railway service."
  note "Each value goes over stdin, so it is not printed here or put in argv."
  say ""
  push_railway_vars
else
  warn "Nothing to push; values are only recorded in $ENV_FILE."
fi
pause

# ──────────────────────────────────────────────────────────────────────────

stage "Railway · public domain"
say "Attach the hostname Cloudflare will proxy to Railway."
open_url "https://railway.com/dashboard"
step "Service → Settings → Networking → Public Networking → Custom Domain."
step "Enter the hostname you will use, for example example.com."
step "Copy the CNAME target Railway shows for it."
say ""
ask RAILWAY_DOMAIN "Hostname added in Railway:"
ask RAILWAY_CNAME_TARGET "CNAME target from Railway:"
if [[ -n "$RAILWAY_DOMAIN" ]]; then
  write_env RAILWAY_DOMAIN "$RAILWAY_DOMAIN"
fi
if [[ -n "$RAILWAY_CNAME_TARGET" ]]; then
  write_env RAILWAY_CNAME_TARGET "$RAILWAY_CNAME_TARGET"
fi
note "No custom domain yet? 'railway domain' prints a *.up.railway.app host."

# ──────────────────────────────────────────────────────────────────────────

stage "Cloudflare · DNS and TLS"
say "Point the hostname at Railway and let Cloudflare terminate TLS."
open_url "https://dash.cloudflare.com"
step "DNS → Records → Add record."
if [[ -n "$RAILWAY_CNAME_TARGET" ]]; then
  step "CNAME | @ | $RAILWAY_CNAME_TARGET | Proxied (orange cloud) | Auto TTL."
else
  step "CNAME | @ | <the Railway CNAME target> | Proxied (orange cloud)."
fi
step "Repeat for www if you use it."
step "SSL/TLS → Overview → Full (strict)."
step "SSL/TLS → Edge Certificates → enable Always Use HTTPS."
say ""
note "If Railway reports the domain as unverified, switch that record to DNS-only"
note "until it verifies, then turn Proxied back on."
note "Do not add cache rules for /api/*, /dashboard/*, /tamu/*, /editor/*,"
note "/checkout/* or /pesanan/*: the app already sends Cache-Control: no-store."
note "Public /w/* pages and static assets are the safe cache candidates."
pause "Press Enter once DNS is configured"

# ──────────────────────────────────────────────────────────────────────────

stage "Neon · apply Prisma migrations"
say "Migrations are deliberate and run against DIRECT_URL, never on app boot."
say "They must land before the deployed app serves writes."
say ""
if confirm "Apply the committed migrations now?"; then
  if railway_linked; then
    say "Running inside the Railway service environment..."
    if ( cd "$REPO_ROOT" && railway run npm run db:migrate:deploy </dev/null ); then
      printf '  %s✓%s migrations applied\n' "$GREEN" "$RESET"
    else
      warn "railway run failed; retrying with the connection strings captured above."
      ( cd "$REPO_ROOT" && DATABASE_URL="$DATABASE_URL" DIRECT_URL="$DIRECT_URL" npm run db:migrate:deploy )
    fi
  else
    say "Running with the connection strings captured above..."
    ( cd "$REPO_ROOT" && DATABASE_URL="$DATABASE_URL" DIRECT_URL="$DIRECT_URL" npm run db:migrate:deploy )
  fi
else
  warn "Skipped. Apply them before the app handles writes."
  SKIPPED+=("Apply migrations: npm run db:migrate:deploy (against DIRECT_URL)")
fi

# ──────────────────────────────────────────────────────────────────────────

stage "Railway · deploy and smoke test"
say "railway.json builds the root Dockerfile and probes /api/health."
say ""
if confirm "Deploy from this machine with 'railway up'?"; then
  if railway_linked; then
    if railway up --detach </dev/null; then
      say "Deployment started. Tail it with: railway logs"
    else
      warn "railway up failed; check 'railway status' and 'railway login'."
      SKIPPED+=("Deploy: run railway up, or push the branch for GitHub autodeploy")
    fi
  else
    warn "Railway CLI is not linked; push the branch for GitHub autodeploy."
    SKIPPED+=("Deploy: push the branch, or link the CLI and run railway up")
  fi
else
  SKIPPED+=("Deploy: push the branch, or run railway up")
fi

say ""
ask SMOKE_HOST "Hostname to smoke test (blank to skip):"
if [[ -n "$SMOKE_HOST" ]]; then
  if ! command -v curl >/dev/null 2>&1; then
    warn "curl is missing; verify https://$SMOKE_HOST/api/health by hand."
    SKIPPED+=("Verify https://$SMOKE_HOST/api/health")
  else
    say "Polling https://$SMOKE_HOST/api/health ..."
    if curl -fsS --retry 10 --retry-delay 6 --retry-connrefused "https://${SMOKE_HOST}/api/health"; then
      printf '\n  %s✓%s health check passed\n' "$GREEN" "$RESET"
    else
      warn "Health check failed; inspect 'railway logs' and DNS propagation."
      SKIPPED+=("Verify https://$SMOKE_HOST/api/health after the deploy settles")
    fi
  fi
else
  note "Skipped. Later: curl -fsS https://<host>/api/health"
fi

# ──────────────────────────────────────────────────────────────────────────

finish
